<script lang="ts">
 import {onMount,tick} from 'svelte'
 import {initialAI,aiTransition} from '../../studies/expansion.mjs'
 let mounted=$state(false),model=$state(initialAI())
 let originalInput=$state<HTMLTextAreaElement>()
 onMount(()=>{mounted=true})
 async function send(type:string,id=0,text=''){model=aiTransition(model,{type,id,text});if(type==='accept'||type==='undo'){await tick();originalInput?.focus()}}
</script>
<section class="task-study" data-study="ai" aria-label="Suggestion and accepted text"><p>Deterministic local simulation. No model call; only the original text is the fictional input context.</p><fieldset disabled={!mounted}><legend class="study-sr">Suggestion controls</legend><label class="study-field">Original text<textarea bind:this={originalInput} class="input" value={model.original} oninput={e=>send('edit',0,e.currentTarget.value)}></textarea></label><div class="study-actions"><button class="btn" onclick={()=>send('start')}>Start or retry suggestion</button><button class="btn" disabled={!model.active} onclick={()=>send('advance')}>Advance partial output</button><button class="btn" disabled={!model.active} onclick={()=>send('stop')}>Stop generation</button><button class="btn" disabled={!model.pending.length} onclick={()=>send('resolve',model.pending[0].id)}>Resolve oldest request</button><button class="btn" disabled={!model.pending.length} onclick={()=>send('resolve',model.pending.at(-1)!.id)}>Resolve newest request</button></div><h4>Suggestion · {model.phase}</h4><p data-suggestion>{model.suggestion||'No suggestion yet.'}</p><div class="study-actions"><button class="btn btn-primary" disabled={model.phase!=='ready'} onclick={()=>send('accept')}>Accept suggestion</button><button class="btn" onclick={()=>send('discard')}>Discard suggestion</button><button class="btn" disabled={!model.undo} onclick={()=>send('undo')}>Undo acceptance</button></div><p role="status">{model.message}</p><button class="btn" onclick={()=>model=initialAI()}>Reset AI simulation</button></fieldset><noscript>Original text and explanation remain readable. Generation controls require JavaScript.</noscript></section>
<style>textarea{width:100%;min-height:6em;resize:vertical;line-height:1.6}</style>
